code.java:
class Solution {
    public int findContentChildren(int[] g,int[] s){
        Arrays.sort(g);
        Arrays.sort(s);
        int child=0;
        for(int cookie:s)if(child<g.length&&cookie>=g[child])child++;
        return child;
    }
}

code.kotlin:
class Solution {
    fun findContentChildren(g:IntArray,s:IntArray):Int{
        g.sort();
        s.sort();
        var child=0;
        for(cookie in s)if(child<g.size&&cookie>=g[child])child++;
        return child
    }
}

code.cpp:
class Solution {
    public: int findContentChildren(vector<int>& g,vector<int>& s){
        sort(g.begin(),g.end());
        sort(s.begin(),s.end());
        int child=0;
        for(int cookie:s)if(child<(int)g.size()&&cookie>=g[child])++child;
        return child;
    }
};
